// Generated by tools/make_fonts.py. Anti-aliased bitmap fonts from the website's
// Young Serif and Figtree (SIL Open Font License 1.1), printable ASCII only.
#pragma once
#include <stdint.h>

typedef struct {
    uint32_t offset;   // into the font's bits, two 4-bit pixels a byte, rows left to right
    uint8_t w, h;
    int8_t x, y;       // top-left of the ink from the pen on the baseline (y is negative: up)
    uint8_t advance;
} glyph_t;

typedef struct {
    const uint8_t *bits;
    const glyph_t *glyphs;  // characters 32..126
    uint8_t ascent, descent;
} font_t;

extern const font_t font_title;  // YoungSerif 18px: screen titles
extern const font_t font_big;  // YoungSerif 28px: the timer and the pairing code
extern const font_t font_body;  // Figtree 11px weight 500: body text
extern const font_t font_label;  // Figtree 10px weight 600: small labels and the header
